<?php
declare(strict_types=1);
namespace App\Application\Assistant\Service;
use App\Application\Assistant\DTO\Request\CreateAssistantConversationRequestDto;use App\Application\Assistant\DTO\Response\AssistantConversationResponseDto;use App\Application\Assistant\Mapper\AssistantResponseMapper;use App\Domain\Assistant\Entity\AssistantConversation;use App\Domain\Assistant\Repository\AssistantConversationRepositoryInterface;use App\Domain\Assistant\Repository\SyllabusEvidenceRetrieverInterface;
final class CreateAssistantConversationService { public function __construct(private readonly AssistantConversationRepositoryInterface $conversations,private readonly SyllabusEvidenceRetrieverInterface $evidence,private readonly AssistantResponseMapper $mapper){} public function createForUser(string $userId,CreateAssistantConversationRequestDto $input):AssistantConversationResponseDto { if ($this->evidence->retrieve($input->syllabusId,'',1)===[]) throw new \DomainException('O edital nao possui paginas extraidas para consulta.');$now=new \DateTimeImmutable('now');$conversation=new AssistantConversation(self::id(),$userId,$input->syllabusId,trim($input->title??'Consulta sobre edital'),$now,$now);$this->conversations->saveConversation($conversation);return $this->mapper->conversation($conversation);} private static function id():string{return bin2hex(random_bytes(16));} }
